"},{"role":"assistant","content":[{"type":"text","text":""}],"tool_calls":[{"id":"call_XibcVswGtxMphrTVst3APTqp","type":"function","function":{"name":"read_file","arguments":"{"target_file":"src/main/java/org/tms/entity/Task.java"}"}}]},{"role":"tool","name":"read_file","tool_call_id":"call_XibcVswGtxMphrTVst3APTqp","content":"package org.tms.entity;

import jakarta.persistence.*;
import java.time.LocalDateTime;

@Entity
@Table(name = "tasks")
public class Task {

 @Id
 @GeneratedValue(strategy = GenerationType.IDENTITY)
 private Long id;

 private String title;
 private String description;
 private String status; // e.g. "TODO", "IN_PROGRESS", "DONE"
 private String priority; // e.g. "LOW", "MEDIUM", "HIGH"
 private LocalDateTime createdAt = LocalDateTime.now();

 // Relation to User (many tasks per user)
 @ManyToOne
 @JoinColumn(name = "user_id")
 private UserEntity userEntity;

 // ✅ Constructors
 public Task() {
 }

 public Task(Long id, String title, String description, String status, String priority, LocalDateTime createdAt, UserEntity userEntity) {
 this.id = id;
 this.title = title;
 this.description = description;
 this.status = status;
 this.priority = priority;
 this.createdAt = createdAt;
 this.userEntity = userEntity;
 }

 // ✅ Getters and Setters
 public Long getId() {
 return id;
 }

 public void setId(Long id) {
 this.id = id;
 }

 public String getTitle() {
 return title;
 }

 public void setTitle(String title) {
 this.title = title;
 }

 public String getDescription() {
 return description;
 }

 public void setDescription(String description) {
 this.description = description;
 }

 public String getStatus() {
 return status;
 }

 public void setStatus(String status) {
 this.status = status;
 }

 public String getPriority() {
 return priority;
 }

 public void setPriority(String priority) {
 this.priority = priority;
 }

 public LocalDateTime getCreatedAt() {
 return createdAt;
 }

 public void setCreatedAt(LocalDateTime createdAt) {
 this.createdAt = createdAt;
 }

 public UserEntity getUser() {
 return userEntity;
 }

 public void setUser(UserEntity userEntity) {
 this.userEntity = userEntity;
 }
