import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.*;
import org.tms.TaskRepository;
import org.tms.entity.Task;
import org.tms.entity.UserEntity;
import org.tms.repository.UserRepository;

import java.security.Principal;
import java.util.List;

@RestController
@RequestMapping("/api/tasks")
public class TaskController {

 @Autowired
 private TaskRepository taskRepository;
 @Autowired
 private UserRepository userRepository;

 @PostMapping
 public Task createTask(@RequestBody Task task, Principal principal) {
 UserEntity userEntity = userRepository.findByUsername(principal.getName()).orElseThrow();
 task.setUser(userEntity);
 return taskRepository.save(task);
 }

 @GetMapping
 public List<Task> getUserTasks(Principal principal) {
 UserEntity userEntity = userRepository.findByUsername(principal.getName()).orElseThrow();
 return taskRepository.findByUserEntity(userEntity);
 }

 @PutMapping("/{id}")
 public Task updateTask(@PathVariable Long id, @RequestBody Task updatedTask) {
 Task task = taskRepository.findById(id).orElseThrow();
 task.setTitle(updatedTask.getTitle());
 task.setDescription(updatedTask.getDescription());
 task.setStatus(updatedTask.getStatus());
 task.setPriority(updatedTask.getPriority());
 return taskRepository.save(task);
 }

 @DeleteMapping("/{id}")
 public String deleteTask(@PathVariable Long id) {
 taskRepository.deleteById(id);
 return "Task deleted";
 }
}
