import io.jsonwebtoken.*;
import io.jsonwebtoken.security.Keys;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.security.Key;
import java.util.Date;

@Service
public class JwtUtil {

 private final Key key;
 private final long jwtExpirationMs;

 public JwtUtil(@Value("${jwt.secret}") String secret,
 @Value("${jwt.expiration-ms}") long jwtExpirationMs) {
 this.key = Keys.hmacShaKeyFor(secret.getBytes());
 this.jwtExpirationMs = jwtExpirationMs;
 }

 public String generateToken(String username) {
 Date now = new Date();
 Date expiry = new Date(now.getTime() + jwtExpirationMs);
 return Jwts.builder()
 .setSubject(username)
 .setIssuedAt(now)
 .setExpiration(expiry)
 .signWith(key, SignatureAlgorithm.HS256)
 .compact();
 }

 public String getUsernameFromToken(String token) {
 return Jwts.parserBuilder().setSigningKey(key).build()
 .parseClaimsJws(token).getBody().getSubject();
 }

 public boolean validateToken(String token) {
 try {
 Jwts.parserBuilder().setSigningKey(key).build().parseClaimsJws(token);
 return true;
 } catch (JwtException | IllegalArgumentException ex) {
 return false;
 }
 }
}
"},{"role":"assistant","content":[{"type":"text","text":""}],"tool_calls":[{"id":"call_L4qWRVhcYvivmSDJeXOROhbc","type":"function","function":{"name":"read_file","arguments":"{"target_file":"src/main/java/org/tms/service/UserService.java"}"}}]},{"role":"tool","name":"read_file","tool_call_id":"call_L4qWRVhcYvivmSDJeXOROhbc","content":"package org.tms.service;

import org.springframework.security.core.userdetails.User;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.security.core.userdetails.UserDetailsService;
import org.springframework.security.core.userdetails.UsernameNotFoundException;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;
import org.tms.entity.Role;
import org.tms.entity.UserEntity;
import org.tms.repository.UserRepository;

import java.util.List;

@Service
public class UserService implements UserDetailsService {

 private final UserRepository userRepository;
 private final PasswordEncoder passwordEncoder;

 public UserService(UserRepository userRepository,
 PasswordEncoder passwordEncoder) {
 this.userRepository = userRepository;
 this.passwordEncoder = passwordEncoder;
 }

 /**
 * Load user by username for authentication (used by Spring Security)
 */
 @Override
 public UserDetails loadUserByUsername(String username) throws UsernameNotFoundException {
 UserEntity user = userRepository.findByUsername(username)
 .orElseThrow(() ->
 new UsernameNotFoundException("User not found with username: " + username));

 return User.builder()
 .username(user.getUsername())
 .password(user.getPassword())
 .roles(user.getRole().name()) // Role Enum (ADMIN/USER)
 .build();
 }

 /**
 * Register new user (default role: USER)
 */
 public UserEntity registerUser(String username, String password) {
 if (userRepository.findByUsername(username).isPresent()) {
 throw new RuntimeException("Username already exists");
 }

 UserEntity user = new UserEntity();
 user.setUsername(username);
 user.setPassword(passwordEncoder.encode(password));
 user.setRole(Role.USER);

 return userRepository.save(user);
 }

 /**
 * Register new admin (for initial setup or restricted API)
 */
 public UserEntity registerAdmin(String username, String password) {
 if (userRepository.findByUsername(username).isPresent()) {
 throw new RuntimeException("Username already exists");
 }

 UserEntity admin = new UserEntity();
 admin.setUsername(username);
 admin.setPassword(passwordEncoder.encode(password));
 admin.setRole(Role.ADMIN);

 return userRepository.save(admin);
 }

 /**
 * Fetch all users — should be accessible only by Admin
 */
 public List<UserEntity> getAllUsers() {
 return userRepository.findAll();
 }
}
"},{"role":"assistant","content":[{"type":"text","text":""}],"tool_calls":[{"id":"call_xhS5oVqggnD3YAQPNAu68iHs","type":"function","function":{"name":"read_file","arguments":"{"target_file":"src/main/java/org/tms/config/SecurityConfig.java"}"}}]},{"role":"tool","name":"read_file","tool_call_id":"call_xhS5oVqggnD3YAQPNAu68iHs","content":"package org.tms.config;



import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.*;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.authentication.dao.DaoAuthenticationProvider;
import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.web.*;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
import org.tms.service.CustomUserDetailsService;
import org.tms.service.JwtUtil;

@Configuration
public class SecurityConfig {

 @Autowired private CustomUserDetailsService userDetailsService;
 @Autowired private JwtUtil jwtUtil;

 @Bean
 public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
 JwtAuthenticationFilter jwtFilter = new JwtAuthenticationFilter(jwtUtil, userDetailsService);

 http.csrf(csrf -> csrf.disable())
 .sessionManagement(sess -> sess.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
 .authorizeHttpRequests(auth -> auth
 .requestMatchers("/api/auth/**").permitAll()
 .anyRequest().authenticated())
 .addFilterBefore(jwtFilter, UsernamePasswordAuthenticationFilter.class);

 return http.build();
 }

 @Bean public BCryptPasswordEncoder passwordEncoder() { return new BCryptPasswordEncoder(); }

 @Bean
 public DaoAuthenticationProvider authenticationProvider() {
 DaoAuthenticationProvider provider = new DaoAuthenticationProvider();
 provider.setUserDetailsService(userDetailsService);
 provider.setPasswordEncoder(passwordEncoder());
 return provider;
 }

 @Bean
 public AuthenticationManager authenticationManager(AuthenticationConfiguration config) throws Exception {
 return config.getAuthenticationManager();
 }
}
"},{"role":"assistant","content":[{"type":"text","text":""}],"tool_calls":[{"id":"call_fkKXS8XOa77Fo3hWSQUgxYFM","type":"function","function":{"name":"read_file","arguments":"{"target_file":"src/main/java/org/tms/service/CustomUserDetailsService.java"}"}}]},{"role":"tool","name":"read_file","tool_call_id":"call_fkKXS8XOa77Fo3hWSQUgxYFM","content":"package org.tms.service;

import org.tms.entity.UserEntity;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.userdetails.*;
import org.springframework.stereotype.Service;
import org.tms.repository.UserRepository;

import java.util.List;

@Service
public class CustomUserDetailsService implements UserDetailsService {
 @Autowired private UserRepository userRepository;

 @Override
 public UserDetails loadUserByUsername(String username) throws UsernameNotFoundException {
 UserEntity userEntity = userRepository.findByUsername(username)
 .orElseThrow(() -> new UsernameNotFoundException("User not found"));
 var authority = new SimpleGrantedAuthority("ROLE_" + userEntity.getRole().name());
 return new org.springframework.security.core.userdetails.User(
 userEntity.getUsername(), userEntity.getPassword(), List.of(authority));
 }
}
