import org.tms.entity.UserEntity;
import org.tms.repository.UserRepository;

import java.util.List;

@RestController
@RequestMapping("/api/admin")
public class AdminController {

 @Autowired
 private UserRepository userRepository;

 // View all users
 @GetMapping("/users")
 public List<UserEntity> getAllUsers() {
 return userRepository.findAll();
 }

 // Delete a user
 @DeleteMapping("/users/{id}")
 public String deleteUser(@PathVariable Long id) {
 userRepository.deleteById(id);
 return "User with ID " + id + " deleted successfully!";
 }

 // Change user role
 @PutMapping("/users/{id}/role")
 public String changeUserRole(@PathVariable Long id, @RequestParam String role) {
 UserEntity userEntity = userRepository.findById(id)
 .orElseThrow(() -> new RuntimeException("User not found"));
 userEntity.setRole(Enum.valueOf(org.tms.entity.Role.class, role.toUpperCase()));
 userRepository.save(userEntity);
 return "User role updated successfully!";
 }
}
